    priority = EXCLUDED.priority,
    remediation_steps = EXCLUDED.remediation_steps,
    is_active = EXCLUDED.is_active,
    updated_at = NOW();

-- Templates not in this seed (e.g. from an older seed) are deactivated rather
-- than deleted, so evidence already saved for past audit runs stays valid.
